package org.openarchive.telegram;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** Static offline instructions. Contains no network references or private user data. */
final class HelpContent {
    static final class Chapter {
        final String title, description;
        Chapter(String title,String description){this.title=title;this.description=description;}
    }
    private static final List<Chapter> ALL;
    static {
        ArrayList<Chapter> chapters=new ArrayList<>();
        chapters.add(new Chapter("1. Быстрый старт: первые три шага",
            "1) Создай и сохрани отдельную копию архива Telegram.\n2) В Telegram Archive открой «Добавить переписку» → «Выбрать папку» или ZIP/RAR.\n3) Дождись окончания импорта, проверь несколько сообщений, фото и видео.\nНе удаляй исходный экспорт — он нужен для восстановления."));
        chapters.add(new Chapter("2. Чаты, поиск, закрепление, избранное",
            "На экране «Мои переписки» нажми чат, чтобы его открыть. Удерживай карточку чата → «Закрепить». Поиск ищет сообщения по словам и участникам. Удерживай сообщение → «★ Добавить в избранное». Избранные сообщения доступны через «Медиа» → «Избранное». Маленьких звёздочек-кнопок в сообщениях нет. Удержание сообщения открывает дополнительные действия."));
        chapters.add(new Chapter("3. Импорт папки, ZIP и RAR",
            "Нажми большую кнопку «Добавить переписку» либо меню ☰ → «Архивы» → «Импортировать чат». Выбери локальный экспорт Telegram в папке, ZIP или RAR. Для больших архивов освободи место заранее и не закрывай приложение во время импорта. Это не загрузка переписки из аккаунта Telegram: данные берутся только из выбранного экспорта."));
        chapters.add(new Chapter("4. Безопасная резервная копия",
            "Меню ☰ → «Архивы» → «Создать резервную копию». Для переноса на новый телефон выбирай ПОЛНУЮ копию: в ней должны быть сообщения, избранное, цитаты со ссылками на источник, история периодов и событий, медиа, аватары, обои и файлы личных заметок. КОМПАКТНАЯ копия НЕ содержит фото, видео, голосовые и вложения заметок. Сохрани копию вне приложения. Затем выбери «Проверить копию» или «Пробное восстановление»: они не должны заменять действующие чаты. Не очищай данные до проверки восстановления на отдельном экземпляре."));
        chapters.add(new Chapter("5. Фото, видео, GIF, кружки, музыка, голосовые",
            "Открой чат → «Медиа» и выбери тип вложения. Нажми на название чата, чтобы открыть разделы. Нажатие открывает просмотр, удержание — меню действий. Если файл отсутствует, проверь, что папка экспорта и медиа доступны. Кружки — отдельный тип MP4. Анимированные TGS-стикеры могут потребовать внешний просмотрщик. Некоторые форматы видео зависят от кодеков телефона."));
        chapters.add(new Chapter("6. Сохранить один файл или сообщение",
            "Удерживай фото, кружок, видео или голосовое → «Сохранить». Изображения и видео можно поместить в галерею, музыку — в системную музыку, другие файлы — в «Загрузки». Текст сообщения можно сохранить в TXT. На Android 8–9 система может попросить выбрать папку. Сохранение создаёт копию и не изменяет оригинал."));
        chapters.add(new Chapter("7. Выбрать и сохранить до 100 файлов",
            "Открой чат → «Медиа» → «Выбрать несколько». Нажимай на нужные вложения, затем «Сохранить». Можно выбрать галерею/музыку по типам или загрузки. Следи за прогрессом. Отмена завершает текущий файл и останавливает оставшуюся очередь. В разных версиях Android системные окна сохранения выглядят по-разному."));
        chapters.add(new Chapter("8. Коллекции: собрать и удалить подборку",
            "В медиатеке удерживай файл → «Добавить в коллекцию», или выбери несколько. «Коллекции» показывает твои подборки без дублирования медиа. В списке коллекций нажми «Управлять» для удаления подборки: исчезнут только ссылки внутри приложения, оригиналы не удаляются. Коллекция не заменяет резервную копию; после изменения путей экспорта некоторые ссылки могут стать недоступны."));
        chapters.add(new Chapter("9. Найти одинаковые файлы",
            "В разделе «Медиа» открой поиск дубликатов и подтверди проверку. Приложение сверяет контрольные суммы SHA-256 одинаковых по содержимому файлов. Проверка ограничена объёмом чтения, может занять время и ничего не удаляет. Похожие картинки с разным размером или сжатием могут не считаться совпадениями."));
        chapters.add(new Chapter("10. Голосовые и формат MP3",
            "Telegram часто сохраняет голосовые как OGG/Opus. При копировании они останутся OGG/Opus: переименование в .mp3 не делает настоящий MP3. Настоящий офлайн-конвертер пока не входит в приложение. Для прослушивания при необходимости выбери совместимый плеер."));
        chapters.add(new Chapter("11. Анализ и статистика диалога",
            "Открой переписку → ⋮ сверху справа → «Анализ переписки». Смотри сообщения, слова, доли участников, виды медиа, графики по дням, неделям, месяцам и годам, активность по часам (00–23), календарь и сравнение людей. Статистика считается локально. Доли по отправителям не означают, кому адресовано сообщение."));
        chapters.add(new Chapter("12. Оформление: темы, обои, аватарки, стекло",
            "Меню ☰ → «Оформление и персонализация» либо внутри переписки ⋮ → «Настроить чат». Здесь выбираются тема, фон чата, аватарки собеседников и групп, цвета, стеклянные карточки. Можно назначить одну аватарку нескольким людям. Лёгкое стекло — градиенты без дорогого размытия, оно не меняет файлы сообщений."));
        chapters.add(new Chapter("13. Плавность и последнее место чтения",
            "В настройках производительности есть автоматический режим, плавный и экономный. Он ограничивает число одновременно отображаемых сообщений и кэш медиа. Приложение старается возвращаться к последнему видимому сообщению. Если устройство нагревается, включи экономный режим или уменьшение анимаций."));
        chapters.add(new Chapter("14. Диагностика при вылете",
            "Меню ☰ → «Диагностика» → системное окно отправки. Отчёт содержит только технические настройки, без текстов сообщений и имён участников. Проверь содержимое перед отправкой. При сбое плеера запиши версию Android, действие и по возможности приложи видеозапись без личной переписки. Не очищай данные приложения."));
        chapters.add(new Chapter("15. Капсула избранного и ограничения",
            "Капсула .tcap — экспериментальный зашифрованный экспорт только избранных текстов. Она не включает вложения и пока не имеет встроенного просмотрщика. Не используй её вместо полноценной резервной копии. Экспорт на внешнее устройство выполняется только твоим действием."));
        chapters.add(new Chapter("16. Где находятся кнопки и как устроен плеер",
            "Главный экран: кнопка «Добавить переписку» — внизу списка; инструкция — только в боковом меню ☰. Внутри чата заголовок открывает сведения, сверху справа ⋮ — поиск, анализ, оформление и закреплённые сообщения. Нижние вкладки — «Переписка» и «Медиа»; избранное находится внутри медиа. Удержание сообщения открывает действия, в том числе избранное и сохранение. Кружок: нажми — воспроизвести или остановить, удерживай плавающий кружок и веди — перемести; крестик на верхней полоске плеера закрывает его. Фотографии: двумя пальцами увеличивай; листай только в обычном масштабе."));
        chapters.add(new Chapter("17. Графики и среднее время между сообщениями",
            "В графиках доступны масштабы 1×, 2×, 3×. Подписи и цвета показывают интенсивность; точное число — нажатием на столбец. Для оценки скорости общения используется время до следующего сообщения другого отправителя при паузе не более 24 часов. Это приближённая оценка, НЕ доказательство ответа на конкретное сообщение; в группах она особенно приблизительна. Частые слова и эмодзи пишутся в кавычках — «1» означает буквально цифру один."));
        chapters.add(new Chapter("18. Цитировать часть сообщения и найти источник",
            "Открой чат, удерживай любое текстовое сообщение → «❞ Цитировать фрагмент». В окне цитаты удерживай текст пальцем и выдели нужную фразу маркерами выделения Android. Если ничего не выделять, берётся весь текст. Нажми «Скопировать», чтобы вставить цитату в другую программу, или «В заметки», чтобы сохранить её внутри Telegram Archive. Заметки открываются через меню ☰ → «Личные заметки»; у сохранённой цитаты есть кнопка «К исходному сообщению», которая вернёт в нужную переписку и подсветит сообщение. Никакая цитата не отправляется в Telegram автоматически; импортированные сообщения не изменяются. Внимание: «Скопировать» помещает текст в системный буфер обмена, который может быть доступен другим приложениям; копируй личное только при необходимости. Заметки хранятся локально и могут исчезнуть при удалении данных приложения."));
        chapters.add(new Chapter("19. Жесты и плавные переходы",
            "Главная → нажми карточку чата. Нажми заголовок чата для сведений о переписке. Внутри чата меню ⋮ открывает поиск, анализ и оформление; «Медиа» показывает только вложения. Удержание сообщения открывает действия; удержание текста в окне цитаты позволяет выделить фрагмент. Переход к исходному сообщению подсвечивает его в контексте. Если анимации мешают, открой настройки производительности и включи уменьшение движения — этот режим делает переходы быстрее и спокойнее."));
        chapters.add(new Chapter("20. Проверка новых возможностей после обновления",
            "Для первого запуска возьми тестовый архив. 1) Открой чаты и убедись, что старые сообщения на месте. 2) Добавь сообщение в избранное долгим нажатием — экран не должен прыгать. 3) Создай цитату → «В заметки» → «К исходному сообщению». 4) Проверь вкладки «Видео», «GIF», «Голосовые» и «Музыка». 5) Включи анализ, проверь графики и проценты. 6) Проверь резервную копию. При любой ошибке не удаляй приложение и не очищай данные."));
        chapters.add(new Chapter("21. Хронология отношений: разметить этапы вручную",
            "Что делает: хранит твои календарные периоды независимо от дат Telegram.\nГде: чат → меню → Хронология → Этапы истории и сравнение графиков.\n1. Нажми «+ Календарный период · любые даты».\n2. Введи название и описание, выбери начало и конец в календаре.\n3. Нажми «Сохранить». Появится карточка с датами.\n4. «Изменить даты / описание» меняет только отметку; «Удалить период» просит подтверждение.\nПример: «Учёба», 1990–1991, даже если чат начинается в 2026 году. Сообщения не создаются, статистика из личного периода автоматически не выводится. Старые этапы по сообщениям остаются ниже. Данные локальные и входят в полную копию. Если кнопки нет, проверь, что открыт экран этапов версии 0.47."));
        chapters.add(new Chapter("22. TGS: анимированные стикеры офлайн",
            "TGS — сжатый GZIP формат Lottie-анимации. В «Медиа» выбери «Стикеры» и нажми на TGS: приложение попытается воспроизвести его локально. Интернет не требуется; размер распакованного файла ограничен ради безопасности. Если конкретный TGS содержит не поддерживаемые рендерером эффекты, приложение покажет ошибку и сохранит оригинальный файл. Анимированные WebM-стикеры используют отдельный формат."));
        chapters.add(new Chapter("23. Кинолента воспоминаний по годам",
            "Открой чат → ⋮ → «Кинолента медиа». Выбери год, затем месяц. Нажми на месяц: появятся не более 18 миниатюр, чтобы большие архивы не зависали. Нажатие открывает медиа, удержание — его действия; остальные файлы доступны в «Медиа». Кинолента выключена по умолчанию, всё происходит локально."));
        chapters.add(new Chapter("24. Хронология: отдельная личная папка",
            "Что делает: объединяет личные события и этапы истории.\nГде: открой чат → меню → Хронология. Для свободных дат открой «Этапы истории и сравнение графиков».\nЛокальный профиль: нажми заголовок чата → «Локальный профиль и заметка» → заполни имя, @username, заметку → «Сохранить». Чтобы очистить поле, удали его текст и сохрани.\nПример: подпись @training в учебном архиве. Подпись не проверяется через Telegram и ничего не отправляет. Она не меняет имена авторов в исходных сообщениях. Каждый чат имеет отдельные поля; полная копия переносит их. Если чат ещё не выбран, сначала открой его."));
        chapters.add(new Chapter("25. Добавить событие, фотографии и голосовые к истории",
            "В переписке удерживай исходное сообщение → «♡ Добавить событие истории». Введи короткое название и описание. Снова открой ⋮ → «Хронология», найди событие, нажми «+ Прикрепить медиа из архива» и выбери фото, видео, кружок, голосовое или файл. В событии сохраняется ССЫЛКА на уже импортированное вложение, а не дополнительная копия. Можно прикреплять несколько разных файлов. Для прикрепления к самому этапу открой «Этапы истории», найди этап и нажми «+ Прикрепить фото, кружок или файл к этапу». Нажми на вложение, чтобы открыть. Удаление события удаляет только отметку и ссылки, оригиналы остаются. Если позже перенесёшь или заменишь экспорт, ссылки могут потребовать проверки."));
        chapters.add(new Chapter("26. Эхо фраз: искать повторяющиеся выражения",
            "Открой чат → ⋮ → «Хронология» → «❞ Эхо фраз». Напечатай слово или фразу из двух и более символов и нажми «Найти повторы». Приложение сравнит текст без различия регистра, покажет число сообщений и буквальных вхождений, затем ссылки на оригиналы. Поиск читает максимум первые 300 000 сообщений за запуск и показывает не более 100 примеров; если лимит достигнут, результат явно обозначен как ЧАСТИЧНЫЙ. Он работает только на телефоне и ничего не отправляет в сеть. Совпадение фразы не является доказательством того, что отношения изменились."));
        chapters.add(new Chapter("27. Переезд на другой телефон: 6 понятных шагов",
            "ШАГ 1 — СТАРЫЙ ТЕЛЕФОН. Открой ☰ → Архивы → Создать резервную копию → ПЕРЕЕЗД: полная копия.\n"+
            "ШАГ 2 — Выбери надёжное место для ZIP или защищённой .tgar, задай пароль по желанию. Убедись, что к исходным медиа и вложениям заметок есть доступ. Не закрывай приложение до завершения.\n"+
            "ШАГ 3 — Нажми Проверить резервную копию и Пробное восстановление. Сверь число чатов, сообщений, избранного, цитат, периодов, событий и файлов.\n"+
            "ШАГ 4 — Перенеси копию на новый телефон безопасным способом (USB или выбранное тобой хранилище). Никому не отправляй личный архив без необходимости.\n"+
            "ШАГ 5 — НОВЫЙ ТЕЛЕФОН. Открой Telegram Archive → Архивы → Восстановить архив; укажи ZIP/.tgar и пароль. Дождись завершения — импорт не должен удалять уже существующие чаты.\n"+
            "ШАГ 6 — Проверь цитату с переходом к исходному сообщению, одну аватарку, кружок, голосовое, стикер, закреплённый чат, свои этапы и одно вложение личной заметки.\n"+
            "Только после этого думай об удалении исходного телефона или резервных файлов. Если восстановление прервалось — НЕ очищай данные, а проверь отчёт диагностики."));
        chapters.add(new Chapter("28. Экспорт чата из Telegram на компьютер",
            "ВАЖНО: официальный массовый экспорт переписки с медиа выполняется через Telegram Desktop на Windows, macOS или Linux — не через наш просмотрщик.\n"
            +"1) Открой Telegram Desktop и нужный чат. В меню чата ⋮ выбери экспорт истории чата, если он доступен. В некоторых версиях экспорт находится в настройках расширенных возможностей.\n"
            +"2) Выбери HTML, отметь фотографии, видео, голосовые, кружки, документы и стикеры. Укажи достаточный предел размера вложений и полный диапазон дат.\n"
            +"3) Дождись завершения экспорта и проверь папку: messages.html или несколько HTML-частей плюс подпапки с медиа. Проверь, что файлы реально лежат рядом.\n"
            +"4) Перенеси всю папку целиком через USB или упакуй в ZIP/RAR. Нельзя переносить только HTML: в нём обычно ссылки на отдельные медиа.\n"
            +"5) В Telegram Archive нажми «Добавить переписку» и выбери папку или архив. Сравни количество сообщений и открой несколько старых фото/видео.\n"
            +"Файлы, которые Telegram Desktop не скачал или не включил в экспорт, просмотрщик восстановить не сможет. Мобильный Telegram и веб-версия могут не предоставлять эквивалентный полный экспорт. Не вводи пароль Telegram в сторонних экспортёрах."));
        chapters.add(new Chapter("29. Сравнение двух переписок",
            "1) На экране «Мои переписки» предварительно импортируй два разных чата.\n"
            +"2) Нажми «Сравнение диалогов». Выбери первый и второй чат.\n"
            +"3) Укажи год, чтобы сравнить активность по 12 месяцам и общий объём сообщений. Сверяй отдельно участников, избранное, фото, видео, голосовые, кружки и другие вложения.\n"
            +"4) При необходимости открой «Воспоминания двух чатов», чтобы увидеть события на общей временной оси и переходить к оригиналам.\n"
            +"Чаты не объединяются в один и не меняются. Доли и периоды не доказывают отношения между людьми. Сравнивай только известные тебе даты и полные экспорты."));
        chapters.add(new Chapter("30. Две переписки на одной линии воспоминаний",
            "1) Импортируй два чата, затем открой «Воспоминания двух чатов» со списка переписок или из раздела «Хронология».\n"
            +"2) Выбери пару переписок, год и при желании месяц.\n"
            +"3) Сообщения отображаются в общей хронологии; у каждого явно показано, к какому исходному чату оно относится.\n"
            +"4) Нажми «Перейти к оригиналу», чтобы открыть это сообщение в его настоящей переписке. Изменение даты лишь фильтрует просмотр.\n"
            +"Программа не объединяет участников и не предполагает связи между сообщениями из разных чатов. Для больших архивов вывод может быть ограничен — это не удаляет данные."));
        chapters.add(new Chapter("31. Навигатор пауз в переписке",
            "1) Открой нужный чат и в боковом меню ☰ выбери «Навигатор пауз».\n"
            +"2) Программа локально проверит до 100 000 сообщений и найдёт до 12 самых длительных пауз не меньше семи суток.\n"
            +"3) Нажми на паузу, затем выбери «До» или «После», чтобы перейти к сообщению на её границе.\n"
            +"4) Если показано «частично», обрати внимание: рассмотрена лишь часть огромного архива.\n"
            +"Пауза не означает потерю сообщений: собеседники могли просто не писать. Данные не изменяются, медиа не скачиваются."));
        chapters.add(new Chapter("32. Премиальный интерфейс и управление видео",
            "Кнопки во всех разделах используют согласованные скругления, световой отклик на нажатие и мягкие переходы. Внешний вид можно менять через ☰ → «Оформление и персонализация».\n"
            +"Воспроизведение видео: открой ролик в «Медиа»; в полноэкранном режиме снизу — перемотка и пауза, сверху — назад и ⚙ со скоростью или внешним плеером. Одиночное нажатие на видео скрывает или возвращает управляющие панели. Во время просмотра панели могут скрыться автоматически.\n"
            +"Для фотографий доступны увеличение двумя пальцами, сдвиг увеличенного кадра, свайп к соседней фотографии, миниатюры снизу.\n"
            +"Чтобы уменьшить эффекты и расход батареи, открой настройки производительности и включи «Уменьшить анимации». Приложение также учитывает системную настройку анимаций Android. Обои и стиль кнопок не изменяют сохранённые сообщения."));
        chapters.add(new Chapter("33. Учебная переписка: попробуй без риска",
            "Открой ☰ → «Учебная переписка» или «Помощь» → «Учебная переписка · попробуй сам». Это отдельная песочница из вымышленных сообщений, НЕ импорт, НЕ реальный Telegram-чат и НЕ копия личных переписок.\n"
            +"1) Нажми на фото, GIF или стикер — появится просмотр.\n"
            +"2) Нажми на видео или кружок — откроется локальное видео, которое можно поставить на паузу.\n"
            +"3) Нажми на голосовое или музыку для воспроизведения демонстрационного звука.\n"
            +"4) Удерживай любое учебное сообщение и выбери «Закрепить». Повтори, чтобы открепить.\n"
            +"5) Удерживай и выбери «Ответить» или «Цитировать», введи текст и нажми «Проверить». Никому ничего не отправляется.\n"
            +"6) Добавь сообщение в учебное избранное, затем убери. Кнопка «Сброс» стирает только учебные действия.\n"
            +"Демо ограничено, не является полноценным Telegram. Все тренировочные изменения живут только до закрытия или сброса учебного экрана. Настоящие базы, заметки, цитаты, обои и медиа остаются неизменными."));
        chapters.add(new Chapter("34. Свои фотографии: обои и аватары",
            "Для собственного фона открой нужную переписку → ☰ → «Обои переписки» → «Своя фотография». Если вызываешь настройку с главного экрана, приложение сначала предложит выбрать переписку, к которой относится фото. Изображение копируется в закрытое хранилище приложения и уменьшается для экономии памяти.\n"
            +"Аватар самого чата: ☰ → «Аватары» → «Аватар чата». Для участников открой чат → ☰ → «Аватары» → выбери участников → «Выбрать фото». Один файл можно назначить нескольким участникам.\n"
            +"Смена обоев не изменяет исходный HTML-экспорт. При удалении приложения пользовательские изображения могут исчезнуть. Перед переездом проверь состав полной резервной копии и тестовое восстановление. Не считай импорт HTML резервной копией настроек."));
        chapters.add(new Chapter("35. Медиатека как галерея",
            "Открой переписку → «Медиа»: выбери тип медиа (фото, видео, GIF, кружки, стикеры, голосовые, музыка). Для фотографий доступны сетка миниатюр, просмотр в полном экране, масштабирование жестом и переход к соседним изображениям.\n"
            +"Удерживай медиа, чтобы открыть его действия; для массовой выгрузки выбирай элементы и запускай пакетное сохранение. Медиа читаются по ссылкам из локального экспорта и не скачиваются из Telegram. Отсутствующий оригинал невозможно восстановить простым кликом по миниатюре.\n"
            +"Рекомендуется хранить оригинальную папку экспорта и резервную копию отдельно. Огромные архивы могут подгружаться порциями, чтобы приложение не зависало."));
        chapters.add(new Chapter("36. Студия оформления 2.0",
            "Меню ☰ → «Открытия» → «Студия оформления 2.0». Посмотри живой пример двух пузырьков, затем выбери тему, обои, аватары, форму или плотность сообщений. Изменения применяются к локальному интерфейсу; при выборе собственного фона обязательно проверь, к какому чату привязана фотография. Для медленных устройств снизь интенсивность анимаций. Перед переносом настроек делай полную резервную копию."));
        chapters.add(new Chapter("37. Медиатека PRO",
            "Открой чат → ☰ → «Медиатека PRO». Выбери «Галерея медиа» для фильтра фото, видео, голосовых, музыки и стикеров; «Кинолента» откроет годы и месяцы; «Мои коллекции» — сохранённые тобой альбомы; «Проверка оригиналов» покажет отсутствующие ссылки. Фото и видео читаются только из папки экспорта. Удаление подборки не удаляет оригинал. Для очень больших архивов миниатюры загружаются порциями."));
        chapters.add(new Chapter("38. Карта истории по месяцам",
            "Открой переписку → ☰ → «Карта истории», введи год. Увидишь 12 месяцев и число импортированных сообщений, затем нажми на месяц, чтобы получить краткий список сообщений с переходом к оригиналу. Данные подсчитываются локально, без ИИ и догадок об отношениях. При обработке более 300 000 строк карта помечается как частичная. Если даты не распознаны или экспорт неполный, счётчики тоже могут быть неполными."));
        chapters.add(new Chapter("39. Капсула времени за выбранный год",
            "Это НЕ видеоролик и НЕ облачный сервис. Сначала отметь интересные сообщения звёздочкой. Потом открой чат → ☰ → «Капсула времени» и введи год: увидишь до 80 избранных сообщений того года с переходом к оригиналам. Можно вернуться к файлам внутри исходной переписки. Новые копии фото и видео не создаются; исходная база не изменяется. Функция не заменяет зашифрованную капсулу .tcap и полную резервную копию."));
        chapters.add(new Chapter("40. Умный поиск по нескольким перепискам",
            "Меню ☰ → «Умный поиск по всем чатам». Введи текст или имя автора (минимум два символа). При желании добавь год и включи «Только сообщения с медиа». Нажми «Найти»: приложение прочитает только локальные базы зарегистрированных переписок и покажет найденные сообщения с названием исходного чата. Нажатие откроет оригинал. Поддерживается максимум 25 чатов, последние 100 000 ID сообщений на чат, по 36 совпадений на чат и 80 в итоговом списке; результаты могут быть ЧАСТИЧНЫМИ. Никакие сообщения не отправляются в Telegram, сервер или сторонний ИИ. Для точного полного поиска используй поиск внутри конкретного чата."));
        chapters.add(new Chapter("41. Шрифты: системный, классические и импорт TTF/OTF",
            "Открой боковое меню ☰ → «Шрифты · изменить везде». По умолчанию выбран системный шрифт Android — как в настройках устройства. "
            +"Выбери Sans, Serif, Monospace, Condensed, Casual, Light или Medium и нажми «Применить» после просмотра образца. "
            +"Шрифт меняется во всех основных экранах: сообщения, заголовки, кнопки, ввод, учебный чат, видео и справка. "
            +"Свой шрифт: скачай законно доступный файл .ttf или .otf, например в пиксельном стиле Minecraft, затем открой «Добавить свой TTF/OTF». "
            +"Выбери файл средствами Android. Программа проверяет расширение, заголовок, размер до 5 МБ и возможность его открыть. "
            +"При ошибке старое оформление сохраняется. Для возврата нажми «Как на устройстве». "
            +"Некоторые декоративные шрифты не содержат русских букв: часть символов тогда будет отображаться запасным системным шрифтом. "
            +"Выбранный файл копируется только в закрытую папку Telegram Archive; никакой сервер не используется. "
            +"Настройки шрифта и импортированный файл могут НЕ переноситься старым форматом резервной копии: сохрани исходный файл отдельно. "
            +"Шрифт не устанавливается в Telegram или во все приложения Android. Не загружай шрифты из недоверенных источников."));
        chapters.add(new Chapter("42. Музыкальный плеер: очередь, обложка, перемотка и скорость",
            "1) Открой нужную переписку, выбери «Медиа», затем раздел «Музыка». Нажми на песню или кнопку «Открыть музыкальный плеер».\n"
            +"2) Откроется отдельный экран с названием песни. Если в самом MP3/M4A/OGG есть название, исполнитель и обложка, они появятся автоматически; иначе программа покажет имя файла и стандартный символ ноты.\n"
            +"3) Нажми ▶ для запуска и Ⅱ для паузы. Проведи ползунок под обложкой для перемотки. Справа от времени — длительность песни.\n"
            +"4) Кнопка ⏮ включает предыдущий трек, ⏭ — следующий. При завершении песни плеер переходит к следующей автоматически, а после последней останавливается. В очереди до 120 песен перед выбранной и 120 после неё.\n"
            +"5) Нажми ⚙ наверху или строку «Скорость» под кнопками, выбери 0,25×, 0,5×, 0,75×, 1×, 1,25×, 1,5× или 2×. Если кодек Android не поддерживает скорость, приложение сообщит об этом.\n"
            +"6) Кнопка ‹ возвращает к медиатеке. Когда приложение свёрнуто, музыка останавливается на паузу — фоновый режим и уведомление пока НЕ реализованы.\n"
            +"ВАЖНО: этот плеер предназначен для музыкальных файлов раздела «Музыка», а не для голосовых или кружков. Он не скачивает и не копирует аудио; оригинальная папка экспорта должна оставаться доступной. Если файл отсутствует или формат не поддерживается, он не будет исправлен автоматически. Интернет и аккаунт Telegram не используются."));
        chapters.add(new Chapter("43. Кружки и голосовые: что делать, если медиа зависло",
            "Кружок — короткий видеофайл. Открой его нажатием в переписке: появится круглый просмотр и полоска перемотки. "
            +"Если на устройстве декодер не показывает первый кадр или останавливается более чем на пять секунд, на кружке появится кнопка «Открыть в плеере». "
            +"Нажми её для полноэкранного просмотра через другой системный видеокомпонент. Это НЕ починка повреждённого файла: если видео не работает и там, сохрани оригинал и проверь его другим приложением. "
            +"Голосовые сообщения учебной переписки теперь имеют кнопку воспроизведения, время и перемотку. Обычный голосовой остаётся OGG/Opus и может не работать на некоторых устройствах. "
            +"В меню «Помощь» есть отдельная глава о видео, музыке и голосовых. Приложение не передаёт файлы по сети и не меняет исходный экспорт."));
        chapters.add(new Chapter("44. Локальный индекс: синонимы и похожие темы",
            "Открой ☰ → «Умный поиск по всем чатам». Введи, например, «Где я благодарю Никиту». "
            +"Отметка «Индекс + локальные синонимы» позволяет найти благодарю/спасибо/признателен и некоторые формы имени, "
            +"если ОБА понятия действительно встречаются в одном сообщении. Слово «я» НЕ определяет, кто автор: укажи своё имя в поле «Автор». Это не распознавание намерений. "
            +"Другой пример: «покупаю тачку» — поиск предлагает купил/покупал и машина/автомобиль. "
            +"Меч и катана — тематически близкие предметы, а НЕ одно и то же. Для таких случаев включи дополнительную галочку "
            +"«Показывать и близкие темы». Она может дать лишние результаты: всегда проверяй исходный текст. "
            +"Поиск работает по локальной SQLite FTS4, без сетевых обращений, без ИИ, не переписывает оригинал. "
            +"В результатах: название чата, дата, настоящий текст, найденные слова и пометка «точно/вариант». "
            +"Нажми результат для перехода к исходному сообщению в переписке. "
            +"Если слова расположены в разных сообщениях или выражены совсем иначе, они могут не найтись — словарь ограничен. "
            +"Показ ограничен до 36 совпадений на чат, 80 всего и максимум 25 чатов за запрос. "
            +"Ограничение списка НЕ означает, что в архиве больше нет совпадений. "
            +"При выключении индексных синонимов включается прежний поиск буквального фрагмента "
            +"с ограничением на последние 100 000 ID. Никаких личных сообщений приложение никуда не отправляет."));
        chapters.add(new Chapter("45. Опечатки, варианты слов и безопасный поиск",
            "1) Открой ☰ → «Умный поиск по всем чатам». Напиши, например, «плахо». "
            +"2) Галочку «Индекс + локальные синонимы» оставь включённой. "
            +"3) ДОПОЛНИТЕЛЬНО поставь «Исправлять опечатки». Поиск прочитает ограниченный словарь "
            +"слов уже имеющегося индекса каждого чата и попробует найти «плохо». Это не нейросеть. "
            +"4) В результате увидишь «исправление опечатки» и настоящее сообщение. Нажми его, чтобы перейти к оригиналу. "
            +"5) Галочка «Показывать и близкие темы» отдельная: она помогает, например, искать катану по теме «меч», "
            +"но НЕ доказывает, что собеседник совершил покупку. Все результаты нужно читать в контексте. "
            +"Опечатки не включены по умолчанию: на слабых телефонах они требуют дополнительного обращения к индексу. "
            +"Поддерживаются лишь однобуквенные ошибки в словах обычно от пяти букв с одинаковым двухбуквенным началом. "
            +"При неподдерживаемом модуле FTS4aux приложение выполняет обычный поиск и сообщает об ограничении. "
            +"Проверяется максимум 650 слов-кандидатов на термин, не больше восьми предлагаемых исправлений. "
            +"Поиск может пропустить опечатки в начале слова и редкие термины: отсутствие результата не означает, "
            +"что сообщение отсутствует. Приложение не читает фото и видео для определения их смысла. "
            +"Медиа и тексты не отправляются в сеть. Старые экспорты остаются без изменений."));
        chapters.add(new Chapter("46. Ответы в Telegram: reply-to и переход к оригиналу",
            "После импорта нового HTML-экспорта Telegram приложение сохраняет внутренние идентификаторы сообщений "
            +"и ссылки «В ответ на…». В переписке над текстом ответа отображается маленькая карточка "
            +"с автором и началом оригинального сообщения. Нажми карточку, чтобы перейти к оригиналу. "
            +"Если оригинал отсутствует в выбранном экспорте, вместо перехода будет честное предупреждение; "
            +"приложение не угадывает сообщение по похожему тексту или расположению. "
            +"Ответы могут вести в другие части messages2.html и далее; все связи вычисляются после чтения всех частей. "
            +"В уже импортированной переписке старой версии ссылки появятся только после нового импорта из исходного HTML. "
            +"Не удаляй старые экспорты: повторный импорт заменяет состав сообщений и может изменить их локальные номера. "
            +"Обновление базы до версии 13 само по себе сохраняет тексты и избранное; отдельное резервное копирование по-прежнему рекомендуется. "
            +"Поиск и просмотр ответов полностью локальны, без загрузки данных в интернет."));
        ALL=Collections.unmodifiableList(chapters);
    }
    static List<Chapter> all(){return ALL;}
    static List<Chapter> find(String query){
        String q=query==null?"":query.trim().toLowerCase(Locale.ROOT);
        if(q.isEmpty())return ALL;
        ArrayList<Chapter> result=new ArrayList<>();
        for(Chapter c:ALL){
            if((c.title+" "+c.description).toLowerCase(Locale.ROOT).contains(q))result.add(c);
        }
        return result;
    }
}
